local bxor = (bit32 and bit32.bxor) or function(a, b)
    local r, p = 0, 1
    while a > 0 or b > 0 do
        if (a % 2) ~= (b % 2) then r = r + p end
        a = math.floor(a / 2)
        b = math.floor(b / 2)
        p = p * 2
    end
    return r
end

local function b64decode(data)
    if crypt and crypt.base64decode then return crypt.base64decode(data) end
    if base64 and base64.decode then return base64.decode(data) end
    if base64_decode then return base64_decode(data) end
    local b, map = {}, {}
    for i = 0, 25 do
        map[string.char(65 + i)] = i
        map[string.char(97 + i)] = i + 26
    end
    for i = 0, 9 do map[string.char(48 + i)] = 52 + i end
    map["+"] = 62
    map["/"] = 63
    data = data:gsub("%s", "")
    local buf, n = 0, 0
    for i = 1, #data do
        local ch = data:sub(i, i)
        if ch == "=" then break end
        local v = map[ch]
        if v then
            buf = buf * 64 + v
            n = n + 1
            if n == 4 then
                b[#b + 1] = string.char(
                    math.floor(buf / 65536) % 256,
                    math.floor(buf / 256) % 256,
                    buf % 256
                )
                buf, n = 0, 0
            end
        end
    end
    if n == 3 then
        buf = buf * 64
        b[#b + 1] = string.char(math.floor(buf / 65536) % 256, math.floor(buf / 256) % 256)
    elseif n == 2 then
        buf = buf * 64 * 64
        b[#b + 1] = string.char(math.floor(buf / 65536) % 256)
    end
    return table.concat(b)
end

local function xorDecode(data)
    local o = table.create and table.create(#data) or {}
    local kl = #_k
    for i = 1, #data do
        o[i] = string.char(bxor(string.byte(data, i), _k[((i - 1) % kl) + 1]))
    end
    return table.concat(o)
end

local parts = table.create and table.create(#_c) or {}
for i = 1, #_c do
    local ok, d = pcall(b64decode, _c[i])
    if not ok or not d then error("[HONKUKI] b64 chunk " .. tostring(i)) end
    parts[i] = xorDecode(d)
end

local src = table.concat(parts)
local fn, err = loadstring(src)
if type(fn) ~= "function" then
    error("[HONKUKI] load: " .. tostring(err))
end
fn()
